  for (y = 1; y < (ssize_t) dds_info->mip_levels; y++)
  {
    register PixelPacket
      *q;

    register ssize_t
      x;

    ssize_t
      rows;

    rows = image->rows >> (size_t) y;
    if (rows == 0)
      break;
    for (y = 1; y < (ssize_t) dds_info->mip_levels; y++)
    {
      offset = (MagickSizeType) pixel_size * (MagickSizeType) image->columns * (MagickSizeType) rows;
      count = SeekBlob(image, offset, SEEK_CUR);
