MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
    if ((dds_info->mipmap_count > 0) && (dds_info->texture_type == Texture || dds_info->texture_type == CubeMap)) {
        MagickSizeType offset = 0;
        MagickSizeType width = image->columns;
        MagickSizeType height = image->rows;

        for (size_t level = 1; level < dds_info->mipmap_count; level++) {
            MagickSizeType level_width = width / 2;
            MagickSizeType level_height = height / 2;

            if (level_width == 0 || level_height == 0)
                level_width = level_height = 1;

            offset += level_width * level_height * pixel_size;

            width = level_width;
            height = level_height;
        }

        if (SeekImageBlob(image, offset, 0) == -1) {
            MagickSetErrorException(exception, UndefinedImageError, "UnableToSeekImageBlob", image);
            return MagickFalse;
        }
    }

    return MagickTrue;
}

MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
  MagickBooleanType status = MagickTrue;
  size_t width = image->columns;
  size_t height = image->rows;

  if ((dds_info->mipmap_count > 1) && (dds_info->is_texture || dds_info->is_cube_map)) {
    while (dds_info->mipmap_count > 1) {
      size_t mipmap_size = width * height * pixel_size;

      if (SeekBlob(image, mipmap_size, SEEK_CUR) != (MagickOffsetType)mipmap_size) {
        (void) ThrowMagickException(exception, GetMagickModule(), CoderError, "Unable to skip mipmap data", " `%s' %s", image->filename, "not enough data");
        return MagickFalse;
      }

      width = width / 2;
      height = height / 2;
      if (width == 0)
        width = 1;
      if (height == 0)
        height = 1;
      dds_info->mipmap_count--;
    }
  }

  return status;
}

MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
    register ssize_t x;

    if ((dds_info->mipmap_count > 1) && (dds_info->texture || dds_info->cube_map)) {
        register ssize_t
            y;

        for (x = 1; x < (ssize_t) dds_info->mipmap_count; x++) {
            size_t
                length;

            length = (size_t) (dds_info->width >> x) * (size_t) (dds_info->height >> x) *
              (size_t) pixel_size;
            if (SeekBlob(image, (ssize_t) length, SEEK_CUR) == (ssize_t) length)
              continue;
            InheritException(exception, &image->exception);
            return(MagickFalse);
        }
    }
    return(MagickTrue);
}

MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
    MagickBooleanType status = MagickTrue;
    size_t width = image->columns;
    size_t height = image->rows;

    if ((dds_info->mipmap_count > 1) && (IsTexture(dds_info) || IsCubeMap(dds_info))) {
        while (dds_info->mipmap_count > 1) {
            size_t row_bytes = width * pixel_size;
            size_t bytes_to_skip = row_bytes * height;

            if (SeekBlob(image, bytes_to_skip, SEEK_CUR) != ( MagickOffsetType ) bytes_to_skip) {
                (void) ThrowMagickException(exception, GetMagickModule(), CoderError, "EndOfFile", "Unable to skip mipmap data");
                status = MagickFalse;
                break;
            }

            dds_info->mipmap_count--;
            width = (width + 1) / 2;
            height = (height + 1) / 2;
        }
    }

    return status;
}
